// added to ~/.pi/agent/trust.json. Placing this bridge in ~/.pi/agent/extensions/
// ensures Entire session tracking and `but commit`/`but push` checkpoint hooks
// run automatically in every repo with `.entire/settings.json` ("enabled": true),
// while deferring cleanly if the project-local extensions already loaded.

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { execFile } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

function findEntireRepoRoot(startDir: string): string | null {
  let current = path.resolve(startDir);
  for (let depth = 0; depth < 32; depth += 1) {
    try {
      const settingsPath = path.join(current, ".entire", "settings.json");
      if (fs.existsSync(settingsPath)) {
        const parsed = JSON.parse(fs.readFileSync(settingsPath, "utf8")) as { enabled?: unknown };
        return parsed?.enabled === true ? current : null;
      }
    } catch {
      return null;
    }
    const parent = path.dirname(current);
    if (parent === current) break;
    current = parent;
  }
  return null;
}

function isEntireEnabled(cwd: string, command?: string): boolean {
  if (findEntireRepoRoot(cwd)) return true;
  if (typeof command === "string") {
    const m = command.match(/\bbut\s+-C\s+(?:"([^"]+)"|'([^']+)'|(\S+))/);
    const raw = m?.[1] || m?.[2] || m?.[3];
    if (raw && findEntireRepoRoot(path.resolve(cwd, raw))) return true;
  }
  return false;
}

