470: export async function runPreflight(options = {}) {
471:   const {
472:     mode = "auto",
473:     strict = false,
474:     issue = null,
475:     cwd = process.cwd(),
476:     homedir = os.homedir(),
477:     env = process.env,
478:     fsImpl = fs,
479:     execFileAsync = defaultExecFileAsync,
480:     fetchImpl = globalThis.fetch,
481:   } = options;
482: 
483:   const effectiveMode =
484:     mode === "auto"
485:       ? fsImpl.existsSync(path.join(cwd, "scripts", "smart-fetch.mjs"))
486:         ? "web-modalities"
487:         : "core"
488:       : mode;
489: 
490:   const checks = [];
491: 
492:   // 1. Node >= 20
493:   const nodeMajor = Number(process.versions.node.split(".")[0]);
494:   checks.push({
495:     name: "cli.node",
496:     status: nodeMajor >= 20 ? "pass" : "fail",
497:     detail: `Node.js v${process.versions.node} (requires >=20)`,
498:   });
499: 
500:   // 2. Core CLIs & auth in parallel
501:   const orcaBin = env.ORCA_CLI_COMMAND || "orca";
502:   const [butRes, entireAuthRes, ghAuthRes, orcaRes] = await Promise.all([
503:     runCmd(execFileAsync, "but", ["--version"]),
504:     runCmd(execFileAsync, "entire", ["auth", "status"]),
505:     runCmd(execFileAsync, "gh", ["auth", "status"]),
506:     runCmd(execFileAsync, orcaBin, ["--version"]),
507:   ]);
508: 
509:   checks.push({
510:     name: "cli.but",
511:     status: butRes.ok ? "pass" : "fail",
512:     detail: butRes.ok ? butRes.stdout.split("\n")[0] : `but unavailable: ${butRes.stderr}`,
513:   });
514:   checks.push({
515:     name: "auth.entire",
516:     status: entireAuthRes.ok ? "pass" : "fail",
517:     detail: entireAuthRes.ok ? "entire authenticated" : `entire auth failed (run 'entire login'): ${entireAuthRes.stderr}`,
518:   });
519:   checks.push({
520:     name: "auth.gh",
521:     status: ghAuthRes.ok ? "pass" : "fail",
522:     detail: ghAuthRes.ok ? "gh authenticated" : `gh auth failed (run 'gh auth login -s project'): ${ghAuthRes.stderr}`,
523:   });
524:   checks.push({
525:     name: "cli.orca",
526:     status: orcaRes.ok ? "pass" : "warn",
527:     detail: orcaRes.ok ? `orca reachable (${orcaRes.stdout.split("\n")[0] || orcaBin})` : `orca CLI not on PATH (${orcaBin})`,
528:   });
529: 
530:   // 3. Repo .entire/settings.json checks
531:   checks.push(...inspectEntireSettings(cwd, fsImpl));
532:   const piHookCheck = checkPiEntireHooks({ cwd, homedir, env, fsImpl });
533:   if (piHookCheck) checks.push(piHookCheck);
534:   const ocHookCheck = checkOpenCodeEntireHooks({ cwd, homedir, env, fsImpl });
535:   if (ocHookCheck) checks.push(ocHookCheck);
536: 
537:   // 4. Optional web-modalities checks
538:   if (effectiveMode === "web-modalities") {
539:     const obscuraRes = await runCmd(execFileAsync, "obscura", ["--version"]);
540:     checks.push({
541:       name: "web.obscura",
542:       status: obscuraRes.ok ? "pass" : "fail",
543:       detail: obscuraRes.ok ? obscuraRes.stdout.split("\n")[0] : `obscura CLI missing: ${obscuraRes.stderr}`,
544:     });
545: 
546:     const smartFetchBin = path.join(homedir, ".local", "bin", "smart-fetch");
547:     const hasSmartFetch = fsImpl.existsSync(smartFetchBin);
548:     checks.push({
549:       name: "web.smart_fetch_symlink",
550:       status: hasSmartFetch ? "pass" : "warn",
551:       detail: hasSmartFetch
552:         ? `${smartFetchBin} present`
553:         : `${smartFetchBin} missing (ln -sf <repo>/scripts/smart-fetch.mjs ~/.local/bin/smart-fetch)`,
554:     });
555: 
556:     const braveSearchScript = path.join(homedir, ".pi", "agent", "skills", "pi-skills", "brave-search", "search.js");
557:     const braveKeyFile = path.join(homedir, ".pi", "brave_api_key.txt");
558:     const hasEnvKey = typeof env.BRAVE_API_KEY === "string" && env.BRAVE_API_KEY.trim().length > 0;
559:     let hasKeyFile = false;
560:     let keyModeOk = true;
561:     if (fsImpl.existsSync(braveKeyFile)) {
562:       const stat = fsImpl.statSync(braveKeyFile);
563:       hasKeyFile = stat.size > 0;
564:       if (process.platform !== "win32") {
565:         keyModeOk = (stat.mode & 0o077) === 0;
566:       }
567:     }
568:     checks.push({
569:       name: "web.brave_search",
570:       status: !fsImpl.existsSync(braveSearchScript)
571:         ? "warn"
572:         : hasEnvKey || (hasKeyFile && keyModeOk)
573:           ? "pass"
574:           : hasKeyFile && !keyModeOk
575:             ? "warn"
576:             : "warn",
577:       detail: !fsImpl.existsSync(braveSearchScript)
578:         ? `Missing ${braveSearchScript}`
579:         : !(hasEnvKey || hasKeyFile)
580:           ? "No BRAVE_API_KEY env or ~/.pi/brave_api_key.txt found"
581:           : !keyModeOk
582:             ? "~/.pi/brave_api_key.txt present but permissions wider than 0600 (run chmod 600 ~/.pi/brave_api_key.txt)"
583:             : "Brave Search CLI + API key present (redacted)",
584:     });
585: 
586:     const mcpPath = path.join(homedir, ".pi", "agent", "mcp.json");
587:     if (!fsImpl.existsSync(mcpPath)) {
588:       checks.push({
589:         name: "web.mcp_config",
590:         status: "warn",
591:         detail: `Missing ${mcpPath} (expected exa + browseros-neo MCP servers)`,
592:       });
593:     } else {
594:       try {
595:         const mcpJson = JSON.parse(fsImpl.readFileSync(mcpPath, "utf8"));
596:         const servers = mcpJson?.mcpServers && typeof mcpJson.mcpServers === "object" ? mcpJson.mcpServers : mcpJson;
597:         const hasExa = Boolean(servers?.exa);
598:         const hasNeo = Boolean(servers?.["browseros-neo"]);
599:         checks.push({
600:           name: "web.mcp_config",
601:           status: hasExa && hasNeo ? "pass" : "warn",
602:           detail: `~/.pi/agent/mcp.json servers: exa=${hasExa}, browseros-neo=${hasNeo}`,
603:         });
604:       } catch (err) {
605:         checks.push({
606:           name: "web.mcp_config",
607:           status: "fail",
608:           detail: `Invalid JSON in ~/.pi/agent/mcp.json: ${err.message}`,
609:         });
610:       }
611:     }
612: 
613:     if (typeof fetchImpl === "function") {
614:       try {
615:         const controller = new AbortController();
616:         const timer = setTimeout(() => controller.abort(), 1500);
617:         const resp = await fetchImpl("http://127.0.0.1:9010/mcp", {
618:           method: "GET",
619:           signal: controller.signal,
620:         });
621:         clearTimeout(timer);
622:         checks.push({
623:           name: "web.browseros_neo_live",
624:           status: "pass",
625:           detail: `BrowserOS Neo reachable on 127.0.0.1:9010 (HTTP ${resp.status})`,
626:         });
627:       } catch {
628:         checks.push({
629:           name: "web.browseros_neo_live",
630:           status: "warn",
631:           detail: "BrowserOS Neo not listening on 127.0.0.1:9010 (launch BrowserOS Neo before Tier 4 fetches)",
632:         });
633:       }
634:     }
635:   }
636: 
637:   // 5. Duplicate-work / claim check (start-of-task only; opt-in via --issue)
638:   if (issue) {
639:     const duplicate = await checkDuplicateWork({ issue, cwd, execFileAsync });
640:     if (duplicate.error) {
641:       checks.push({
642:         name: "workflow.duplicate_work",
643:         status: "warn",
644:         detail: duplicate.error,
645:       });
646:     } else if (duplicate.ok) {
647:       checks.push({
648:         name: "workflow.duplicate_work",
649:         status: "pass",
650:         detail: `No open PRs, worktrees, or branches already claim #${issue}`,
651:       });
652:     } else {
653:       const detail = duplicate.duplicates
654:         .map((d) => `${d.label} (${d.detail})`)
655:         .join("; ");
656:       checks.push({
657:         name: "workflow.duplicate_work",
658:         status: "fail",
659:         detail: `${duplicate.duplicates.length} item(s) already claim #${issue}: ${detail}. Resume the existing worktree/branch instead of spawning a new one.`,
660:       });
661:     }
662:   }
663: 
664:   const failed = checks.filter((c) => c.status === "fail" || (strict && c.status === "warn"));
665:   return {
666:     ok: failed.length === 0,
667:     mode: effectiveMode,
668:     checks,
669:   };
670: }
