672: export async function runCompletionGate(options = {}) {
673:   const {
674:     branch: rawBranch = null,
675:     issue = null,
676:     repo: rawRepo = null,
677:     projectOwner = "zzztimbo",
678:     projectNumber = 1,
679:     strict = false,
680:     env = process.env,
681:     execFileAsync = defaultExecFileAsync,
682:   } = options;
683: 
684:   const checks = [];
685:   const orcaBin = env.ORCA_CLI_COMMAND || "orca";
686: 
687:   // Resolve current Orca worktree first (gives default branch/issue/repo if omitted)
688:   const orcaCurrent = await runCmd(execFileAsync, orcaBin, ["worktree", "current", "--json"]);
689:   let worktree = null;
690:   if (orcaCurrent.ok && orcaCurrent.stdout) {
691:     try {
692:       worktree = JSON.parse(orcaCurrent.stdout)?.result?.worktree ?? null;
693:     } catch {
694:       worktree = null;
695:     }
696:   }
697: 
698:   const branch =
699:     rawBranch ||
700:     (typeof worktree?.branch === "string" ? worktree.branch.replace(/^refs\/heads\//, "") : null);
701:   const issueNumber = issue ?? worktree?.linkedIssue ?? null;
702:   const repo =
703:     rawRepo ||
704:     (typeof worktree?.projectId === "string" && worktree.projectId.startsWith("github:")
705:       ? worktree.projectId.slice("github:".length)
706:       : null);
707: 
708:   if (!branch) {
709:     return {
710:       ok: false,
711:       gate: "in-review",
712:       checks: [{ name: "gate.branch", status: "fail", detail: "Pass --branch <branch> (could not infer from Orca worktree)" }],
713:     };
714:   }
715: 
716:   // 1. GitHub Shadow PR check (including draft, merge-conflict & behind-base detection)
717:   const ghPrArgs = ["pr", "view", branch, "--json", "number,title,body,url,state,isDraft,mergeable,mergeStateStatus"];
718:   if (repo) ghPrArgs.push("--repo", repo);
719:   const prRes = await runCmd(execFileAsync, "gh", ghPrArgs);
720:   let prNumber = null;
721:   if (!prRes.ok) {
722:     checks.push({
723:       name: "gate.shadow_pr",
724:       status: "fail",
725:       detail: `No GitHub PR found for branch "${branch}": ${prRes.stderr}`,
726:     });
727:   } else {
728:     const pr = JSON.parse(prRes.stdout);
729:     prNumber = pr.number;
730:     const { hasShadowMarker, hasIssueClosingKeyword } = validateShadowPrBody(pr.body, issueNumber);
731:     checks.push({
732:       name: "gate.shadow_pr_open",
733:       status: pr.state === "OPEN" && pr.isDraft !== true ? "pass" : "fail",
734:       detail:
735:         pr.isDraft === true
736:           ? `PR #${pr.number} (${pr.url}) is still DRAFT — run 'entire trail ready <T> --branch ${branch}'`
737:           : `PR #${pr.number} (${pr.url}) state=${pr.state} (ready for review)`,
738:     });
739:     const hasConflict = pr.mergeable === "CONFLICTING" || pr.mergeStateStatus === "DIRTY";
740:     const isBehind = pr.mergeStateStatus === "BEHIND";
741:     checks.push({
742:       name: "gate.shadow_pr_mergeable",
743:       status: hasConflict || isBehind ? "fail" : "pass",
744:       detail: hasConflict
745:         ? `PR #${pr.number} has MERGE CONFLICTS (mergeable=${pr.mergeable}, mergeStateStatus=${pr.mergeStateStatus}) — run 'but pull', resolve with 'but resolve', re-test, and 'but push ${branch}'`
746:         : isBehind
747:           ? `PR #${pr.number} is BEHIND base branch (mergeStateStatus=${pr.mergeStateStatus}) — run 'but pull' and 'but push ${branch}'`
748:           : `PR #${pr.number} conflict-free (mergeable=${pr.mergeable ?? "MERGEABLE"}, mergeStateStatus=${pr.mergeStateStatus ?? "CLEAN"})`,
749:     });
750:     checks.push({
751:       name: "gate.shadow_pr_marker",
752:       status: hasShadowMarker ? "pass" : "fail",
753:       detail: hasShadowMarker
754:         ? "PR body preserves <!-- entire-shadow-pr -->"
755:         : "PR body is missing <!-- entire-shadow-pr --> (re-add via gh pr edit)",
756:     });
757:     if (issueNumber) {
758:       checks.push({
759:         name: "gate.shadow_pr_fixes_issue",
760:         status: hasIssueClosingKeyword ? "pass" : "fail",
761:         detail: hasIssueClosingKeyword
762:           ? `PR body links closing keyword for #${issueNumber}`
763:           : `PR body missing 'Fixes #${issueNumber}' (update via gh pr edit preserving <!-- entire-shadow-pr -->)`,
764:       });
765:     }
766:   }
767: 
768:   // 2. Entire Trail & review/approval gates
769:   const trailArgs = ["trail", "show", "--branch", branch, "--json"];
770:   if (repo) trailArgs.push("--repo", `gh/${repo}`);
771:   const trailRes = await runCmd(execFileAsync, "entire", trailArgs, 20000);
772:   if (!trailRes.ok) {
773:     checks.push({
774:       name: "gate.entire_trail",
775:       status: "fail",
776:       detail: `No Entire Trail found for branch "${branch}": ${trailRes.stderr}`,
777:     });
778:   } else {
779:     const trailJson = JSON.parse(trailRes.stdout);
780:     const gateEval = evaluateTrailGates(trailJson, branch);
781:     checks.push({
782:       name: "gate.entire_trail_gates",
783:       status: gateEval.ok ? "pass" : "fail",
784:       detail: `${gateEval.detail}${gateEval.trailUrl ? ` (${gateEval.trailUrl})` : ""}`,
785:     });
786:   }
787: 
788:   // 2b. Entire checkpoints & commit trailers check
789:   const cpChecks = await checkBranchCheckpoints({ branch, execFileAsync });
790:   checks.push(...cpChecks);
791: 
792:   // 3. Orca worktree status + linked PR (non-blocking when running inside OpenChamber outside an Orca pane)
793:   const inOpenChamber = Boolean((env.OPENCHAMBER_HOST || env.OPENCHAMBER_RUNTIME) && !env.ORCA_PANE_KEY);
794:   if (!worktree || inOpenChamber) {
795:     checks.push({
796:       name: "gate.orca_worktree",
797:       status: "warn",
798:       detail: inOpenChamber
799:         ? "Running inside OpenChamber outside an Orca pane (skipped Orca workspaceStatus check)"
800:         : "Current directory is not an active Orca worktree (skipped Orca status check)",
801:     });
802:   } else {
803:     const wsStatus = worktree.workspaceStatus;
804:     const linkedPr = worktree.linkedPR;
805:     const hasLinkedPrInItems = Array.isArray(worktree.linkedItems)
806:       ? worktree.linkedItems.some((item) => item.type === "pr" || item.type === "pull_request")
807:       : false;
808:     checks.push({
809:       name: "gate.orca_workspace_status",
810:       status: wsStatus === "in-review" ? "pass" : "fail",
811:       detail:
812:         wsStatus === "in-review"
813:           ? "Orca workspaceStatus=in-review"
814:           : `Orca workspaceStatus="${wsStatus}" (run: orca worktree set --worktree active --workspace-status in-review --comment "...")`,
815:     });
816:     checks.push({
817:       name: "gate.orca_linked_pr",
818:       status: linkedPr || hasLinkedPrInItems ? "pass" : "fail",
819:       detail:
820:         linkedPr || hasLinkedPrInItems
821:           ? `Orca worktree linked to PR #${linkedPr ?? prNumber ?? "attached"}`
822:           : `Orca worktree missing PR reference (run: orca reference add <PR_URL> --worktree current --json)`,
823:     });
824:   }
825: 
826:   // 4. GitHub Project #1 status check (when issueNumber is known)
827:   if (issueNumber && repo) {
828:     const projRes = await runCmd(
829:       execFileAsync,
830:       "gh",
831:       ["project", "item-list", String(projectNumber), "--owner", projectOwner, "--format", "json", "--limit", "100"],
832:       20000,
833:     );
834:     if (!projRes.ok) {
835:       checks.push({
836:         name: "gate.github_project_status",
837:         status: "warn",
838:         detail: `Could not query GitHub Project #${projectNumber}: ${projRes.stderr}`,
839:       });
840:     } else {
841:       const items = JSON.parse(projRes.stdout)?.items ?? [];
842:       const item = items.find(
843:         (it) => it?.content?.number === issueNumber && String(it?.content?.repository ?? "").toLowerCase() === repo.toLowerCase(),
844:       );
845:       if (!item) {
846:         checks.push({
847:           name: "gate.github_project_status",
848:           status: "warn",
849:           detail: `Issue #${issueNumber} is not on GitHub Project #${projectNumber} (optional if not tracked on board)`,
850:         });
851:       } else {
852:         checks.push({
853:           name: "gate.github_project_status",
854:           status: item.status === "In Review" ? "pass" : "fail",
855:           detail:
856:             item.status === "In Review"
857:               ? `GitHub Project #${projectNumber} Status="In Review" for #${issueNumber}`
858:               : `GitHub Project #${projectNumber} Status="${item.status}" for #${issueNumber} (expected "In Review")`,
859:         });
860:       }
861:     }
862:   }
863: 
864:   const failed = checks.filter((c) => c.status === "fail" || (strict && c.status === "warn"));
865:   return {
866:     ok: failed.length === 0,
867:     gate: "in-review",
868:     branch,
869:     issue: issueNumber,
870:     repo,
871:     checks,
872:   };
873: }
