875: function formatReport(result) {
876:   const icon = (s) => (s === "pass" ? "PASS" : s === "warn" ? "WARN" : "FAIL");
877:   const header = result.gate
878:     ? `Completion Gate (${result.gate}) — branch=${result.branch}${result.issue ? ` issue=#${result.issue}` : ""}`
879:     : `Preflight Check (mode=${result.mode})`;
880:   const lines = [header, "-".repeat(header.length)];
881:   for (const c of result.checks) {
882:     lines.push(`[${icon(c.status)}] ${c.name}: ${c.detail}`);
883:   }
884:   lines.push(`Result: ${result.ok ? "READY" : "NOT READY"}`);
885:   return lines.join("\n");
886: }
